import { Application } from '@znight/core'

// Generated by the compiler (znight generate, vite build, bun test): every provider, its
// dependencies, the routes and the GraphQL schema as data. Only this file and the tests import it.
import { __ZNIGHT_METADATA__ } from './.znight/container.generated.js'
import { plugins } from './plugins.js'

const app = await Application.create({
  metadata: __ZNIGHT_METADATA__,
  plugins: plugins(),
  // SIGINT / SIGTERM: HTTP stops accepting connections and drains the requests in flight; the
  // subscription streams end without `complete` (GraphQL-over-SSE clients reconnect to another
  // instance), their `ctx.signal` aborts and the PubSub subscriptions close; then providers stop.
  // Keep `timeoutMs` below the grace period of your platform (Kubernetes: 30 s, `docker stop`: 10 s).
  shutdown: { timeoutMs: 8_000, hookTimeoutMs: 5_000 },
})

// POST /graphql, GET /graphql (queries; GraphiQL in development), subscriptions over SSE, GET /health
await app.start()
